import {demoCreators,defaultCampaign,scoreCreator} from './data.js';
import {researchHTML,researchDetailHTML,bindResearch,exportShortlist} from './discovery.js';
let creators=[...demoCreators];
const key='prenew-copilot-v1', labels={content:'Content relevance',market:'Audience market',language:'Content language',performance:'Recent performance',campaign:'Campaign fit'},statuses=['Shortlisted','Ready to Contact','Contacted','Replied','Confirmed'];
let state={campaign:{...defaultCampaign},weights:{content:30,market:20,language:20,performance:10,campaign:20},pipeline:{},saved:false};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.campaign&&saved?.weights&&saved?.pipeline)state=saved;}catch{}
if(!['Germany','Finland','France','Sweden','United Kingdom'].includes(state.campaign.country))state.campaign.country='Finland';
if(!['German','English','French','Finnish','Swedish'].includes(state.campaign.language))state.campaign.language='Finnish';
state.records??={};
creators=[...demoCreators,...Object.values(state.records)];
let view='research',selected=null,compare=[],search='',platform='All platforms',sort='fit',compareView=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n==null?'Unknown':'€'+Number(n).toLocaleString('en-GB');const num=n=>n==null?'Unknown':n>=1000?(n/1000).toFixed(1)+'k':n;
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Storage unavailable. Changes will last only for this session.')}}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3500)}
function fit(c){return scoreCreator(c,state.campaign,state.weights)}
function reason(c){return `${c.topic} content ${c.goal===state.campaign.goal?'aligns with':'could be adapted to'} the ${state.campaign.goal==='buyers'?'PC buyer':'PC seller'} campaign. ${c.language===state.campaign.language?c.language+' content matches the brief.':'Language differs from the brief.'} ${c.audienceCountry===null?'Audience location is unknown.':c.audienceCountry===state.campaign.country?'Sample audience market matches.':'Sample audience market differs.'}`}
function options(values,current){return values.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('')}
function shell(content){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">prenew<span>↗</span></div><small>CREATOR COPILOT</small><nav class="nav">${[['research','01','Discover creators'],['pipeline','02','Shortlist & pipeline'],['campaign','03','Campaign'],['discover','04','Demo library']].map(([v,n,t])=>`<button data-nav="${v}" class="${view===v?'active':''}">${n} &nbsp; ${t}</button>`).join('')}</nav><div class="sidefoot"><span class="pill lime">HACKATHON PROTOTYPE</span><p>A second life for PCs.<br>A better fit for creators.</p><small>Local workspace · No messages sent</small></div></aside><main class="main"><div class="topbar"><span>Workspace &nbsp; / &nbsp; <b>${view==='campaign'?'Campaign setup':esc(state.campaign.name)}</b></span><span class="pill lime">${view==='discover'?'DEMO EXAMPLES':'LOCAL WORKSPACE'}</span></div>${content}</main></div>`;bind();bindResearch({state,save,render,select:id=>{selected=id;render();window.scrollTo(0,0)},ensure,creators:()=>creators,toast})}
function render(){creators=[...demoCreators,...Object.values(state.records||{})];if(selected){const c=creators.find(x=>x.id===selected);if(c?.sourceType)return shell(researchDetailHTML(c,state));return detail();}if(view==='research')return shell(researchHTML(state));if(view==='campaign')return campaign();if(view==='pipeline')return pipeline();discover()}
function campaign(){const c=state.campaign;shell(`<div class="eyebrow">A good collaboration starts with a clear brief</div><h1>Build your next campaign.</h1><p class="muted">Give the copilot a direction. Keep every decision in your hands.</p><div class="steps"><b>01 &nbsp; Campaign brief</b><span>02 &nbsp; Find your creators</span><span>03 &nbsp; Create & approve</span></div><div class="banner">One campaign per local workspace. Changing the brief clears existing drafts and approvals and returns creators to Shortlisted, so outreach can be reviewed against the new brief.</div><form id="campaign-form" class="panel"><div class="formgrid"><label class="full">Campaign name<input name="name" required maxlength="120" value="${esc(c.name)}"></label><label>Campaign goal<select name="goal"><option value="buyers" ${c.goal==='buyers'?'selected':''}>Attract PC buyers</option><option value="sellers" ${c.goal==='sellers'?'selected':''}>Find people selling old PCs</option></select></label><label>Total campaign budget (€)<input type="number" name="budget" min="1" max="1000000" required value="${c.budget}"></label><label>Target country<select name="country">${options(['Germany','Finland','France','Sweden','United Kingdom'],c.country)}</select></label><label>Content language<select name="language">${options(['German','English','French','Finnish','Swedish'],c.language)}</select></label><label>Target audience<input name="audience" required value="${esc(c.audience)}"></label><label>Product / PC category<input name="category" required value="${esc(c.category)}"></label><label>Preferred platform<select name="platform">${options(['All platforms','YouTube','Twitch','TikTok'],c.platform)}</select></label><label class="full">Supplied product facts<textarea name="facts" required>${esc(c.facts)}</textarea><small>Only supplied facts are used in drafts. Add verified pricing, specs or terms here if available.</small></label></div><div class="actions"><button class="primary" type="submit">Save campaign & discover creators →</button></div></form>`)}
function card(c){const f=fit(c);return `<article class="card"><div class="row"><span class="pill">${c.platform} · SAMPLE</span><label class="check"><input type="checkbox" data-compare="${c.id}" ${compare.includes(c.id)?'checked':''}> Compare</label></div><div class="row"><div class="identity"><div class="avatar">${c.name.split(' ').slice(0,2).map(x=>x[0]).join('')}</div><div><h3>${c.name}</h3><small>${c.country} · ${c.language}</small></div></div><div class="score" title="Weighted score over known factors">${f.score??'—'}<small>/100</small></div></div><span class="muted">${c.topic}</span><div class="metrics"><div><strong>${num(c.followers)}</strong><small>Followers</small></div><div><strong>${num(c.recentViews)}</strong><small>Avg. views*</small></div><div><strong>${money(c.fee)}</strong><small>Sample fee</small></div></div><p class="reason">${reason(c)}</p><small>${f.known}/5 factors known ${c.fee>state.campaign.budget?'· Over campaign budget':''}</small><button data-detail="${c.id}">Explore fit & collaboration ↗</button></article>`}
function discover(){let list=demoCreators.filter(c=>(platform==='All platforms'||c.platform===platform)&&`${c.name} ${c.topic} ${c.country} ${c.language}`.toLowerCase().includes(search.toLowerCase()));list.sort((a,b)=>sort==='fee'?(a.fee??Infinity)-(b.fee??Infinity):sort==='reach'?b.followers-a.followers:(fit(b).score??-1)-(fit(a).score??-1));shell(`<div class="head"><div><div class="eyebrow">Creator discovery</div><h1>Find your next great fit.</h1><p class="muted">Gaming voices with a reason to collaborate.</p></div><button data-nav="campaign">Edit campaign ↗</button></div><div class="stats"><div class="stat"><small>CAMPAIGN GOAL</small><strong>${state.campaign.goal==='buyers'?'Attract buyers':'Find sellers'}</strong><small>${esc(state.campaign.country)} · ${esc(state.campaign.language)}</small></div><div class="stat"><small>CREATOR POOL</small><strong>20 <small>sample profiles</small></strong><small>YouTube, Twitch & TikTok</small></div><div class="stat"><small>CAMPAIGN BUDGET</small><strong>${money(state.campaign.budget)}</strong><small>Fees require creator confirmation</small></div></div><div class="banner">Demo dataset: all identities, content and metrics are fictional. No live audience data, verified fees or collaboration interest. *Average views: illustrative last 5 uploads / streams over 30 days; platform metrics are not directly comparable.</div><details class="panel"><summary>Recommendation controls <span class="muted">· adjust the weight of each factor</span></summary><p class="muted">Scores are weighted averages of known factors only. Unknown factors are excluded, not scored as zero. Scores with less evidence are less reliable. Fee is a budget check, not a score.</p>${Object.entries(labels).map(([k,l])=>`<label class="weight">${l}<input type="range" min="0" max="100" value="${state.weights[k]}" data-weight="${k}"><span>${state.weights[k]}</span></label>`).join('')}<small>Content: 65–95 by topic. Market: 100 match / 30 mismatch. Language: 100 / 20. Performance: average views ÷ followers, capped at 100. Campaign: 100 primary goal / 45 adjacent goal. These are adjustable prototype heuristics, not predicted outcomes.</small></details><div class="toolbar"><input id="search" aria-label="Search creators" placeholder="Search creators, topics or markets…" value="${esc(search)}"><select id="platform" aria-label="Filter platform">${options(['All platforms','YouTube','Twitch','TikTok'],platform)}</select><select id="sort" aria-label="Sort creators"><option value="fit" ${sort==='fit'?'selected':''}>Best fit first</option><option value="fee" ${sort==='fee'?'selected':''}>Lowest known fee</option><option value="reach" ${sort==='reach'?'selected':''}>Largest following</option></select></div><div class="row"><h3>${list.length} creators to explore</h3><small>Personalized to your campaign</small></div>${compareView?comparison():''}<div class="grid">${list.map(card).join('')}</div>${!list.length?'<div class="empty">No matches. Try another topic or platform.</div>':''}${compare.length?`<div class="compare row"><span>${compare.length} / 3 creators selected</span><button id="compare-show">${compareView?'Hide comparison':'Compare side by side'}</button></div>`:''}`)}
function comparison(){const cs=demoCreators.filter(c=>compare.includes(c.id));return `<div class="panel tablewrap"><table><thead><tr><th>Compare evidence</th>${cs.map(c=>`<th>${c.name}</th>`).join('')}</tr></thead><tbody>${[['Fit score',c=>fit(c).score??'Unknown'],['Known factors',c=>fit(c).known+'/5'],['Content',c=>c.topic],['Language',c=>c.language],['Audience market',c=>c.audienceCountry??'Unknown'],['Average views',c=>num(c.recentViews)],['Estimated fee (demo)',c=>money(c.fee)],['Conflict',c=>c.conflict??'Unknown — needs checking']].map(([l,fn])=>`<tr><td>${l}</td>${cs.map(c=>`<td>${esc(fn(c))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function ideas(c){const cat=state.campaign.category;return state.campaign.goal==='buyers'?[{title:`The ${cat} test`,body:`A ${c.platform} ${c.topic.toLowerCase()} feature for ${state.campaign.audience}. Agree on the exact PC and test games together. Report measured results, not promised frame rates.`},{title:'Refurbished vs. new: an honest comparison',body:`Compare an agreed refurbished system with a similarly priced new option. Show prices on the test date and explain tradeoffs; do not assume a winner.`},{title:'What is it like to buy refurbished?',body:`Document a purchase journey and first impressions. Confirm Prenew’s actual process and terms before scripting. Keep the creator’s review independent.`}]:[{title:'The old rig audit',body:`Help ${state.campaign.audience} inventory an old gaming PC: components, condition and questions to ask before selling. Adapt it to ${c.topic.toLowerCase()} on ${c.platform}.`},{title:'From spare PC to next setup',body:'Follow the preparation of an old gaming PC for sale. Confirm Prenew’s selling process, accepted hardware and terms first; do not promise a payout.'},{title:'Keep, upgrade or sell?',body:'Compare practical options for an older PC. Include selling through Prenew as an option without assuming a valuation or guaranteed sale.'}];}
function detail(){const c=creators.find(c=>c.id===selected),f=fit(c),p=state.pipeline[c.id],concepts=ideas(c);shell(`<button class="back" id="back">← Back to ${view==='pipeline'?'pipeline':'creators'}</button><div class="head"><div><div class="eyebrow">${c.platform} · Fictional sample creator</div><h1>${c.name}</h1><p class="muted">${c.topic} &nbsp; / &nbsp; ${c.country} · ${c.language}</p></div><button class="primary" id="shortlist">${p?'✓ '+p.status:'＋ Add to shortlist'}</button></div><div class="layout"><div class="stack"><section class="panel"><div class="row"><h2>Why this creator?</h2><strong class="score">${f.score??'—'}/100</strong></div><p>${reason(c)}</p>${Object.entries(f.factors).map(([k,v])=>`<div class="row"><span>${labels[k]}</span><b>${v===null?'Unknown':v+'/100'}</b></div><div class="bar"><i style="width:${v??0}%"></i></div>`).join('')}<small>${f.known}/5 factors known. See discovery controls for formulas and weights. Creator location is not used as a substitute for audience location.</small></section><section class="panel"><h2>Content & evidence</h2><span class="pill">ILLUSTRATIVE CONTENT</span><h3>${c.contentTitle}</h3><p class="muted">${num(c.recentViews)} average views · ${c.engagement===null?'Unknown engagement':c.engagement.toFixed(1)+'% sample engagement'}<br>Last 5 uploads / streams, illustrative 30-day window. No data was fetched.</p><a href="examples.html?creator=${c.id}" target="_blank" rel="noopener">Open sample content brief ↗</a><p class="muted">This local example is a fictional content brief, not a real creator video. Source: seeded demo dataset.</p></section><section class="panel"><h2>What needs checking</h2><p>Audience country: <b>${c.audienceCountry??'Unknown'}</b> ${c.audienceCountry?'(demo assumption)':''}. Age distribution, actual fee, exclusivity and willingness to collaborate are unknown.</p><p>${c.conflict??'No conflict information supplied. Check sponsorship history and competing marketplace agreements.'}</p><p class="muted">${c.fee===null?'Fee is unknown. Request a quote.':'Illustrative fee: '+money(c.fee)+'. '+(c.fee>state.campaign.budget?'Exceeds the total campaign budget.':'Not a verified quote; production costs and taxes are not included.')}</p></section></div><div class="stack"><section class="panel"><span class="eyebrow">01 / Collaboration concept</span><h2>A natural starting point.</h2><p class="muted">Three template-generated ideas, adapted to this brief. Select one to shape your outreach.</p>${concepts.map((x,i)=>`<button class="idea ${p?.concept===i?'selected':''}" data-idea="${i}"><strong>${esc(x.title)}</strong>${esc(x.body)}</button>`).join('')}</section><section class="panel"><span class="eyebrow">02 / Personal outreach</span><h2>Make the first move.</h2><button id="generate" class="dark" ${p?.concept==null?'disabled':''}>${p?.draft?'Regenerate draft':'Generate outreach draft'}</button>${p?.draft?`<label style="margin-top:18px">Editable draft<textarea id="draft" class="outreach">${esc(p.draft)}</textarea></label><small>Drafts are in English for this demo. Translate and review for ${esc(state.campaign.language)} before real use. Editing an approved draft requires reapproval.</small><div class="actions"><button class="primary" id="approve" ${p.approved?'disabled':''}>${p.approved?'✓ Approved':'Approve draft'}</button><button data-nav="pipeline">View pipeline →</button></div>`:'<p class="muted">Choose a concept above to unlock your draft.</p>'}<p class="muted">Nothing is sent. Approval marks this creator Ready to Contact.</p></section></div></div>`)}
function ensure(id){return state.pipeline[id]??(state.pipeline[id]={status:'Shortlisted',concept:null,draft:'',approved:false})}
function draft(c,p){return `Subject: ${state.campaign.name} — a Prenew collaboration idea\n\nHi ${c.name} team,\n\nYour focus on ${c.topic.toLowerCase()} caught our attention, particularly the sample concept “${c.contentTitle}”. [Replace this demo reference with a verified video before use.]\n\nI’m reaching out from Prenew about a campaign for ${state.campaign.audience} in ${state.campaign.country}, focused on ${state.campaign.goal==='buyers'?'buying refurbished gaming PCs':'selling old gaming PCs'}.\n\n${state.campaign.facts}\n\nOne idea: ${ideas(c)[p.concept].title}. ${ideas(c)[p.concept].body}\n\nWould this be interesting to explore? We’d love to hear about your audience fit, availability and rates for ${c.platform}. We can agree on the product details, deliverables, compensation and sponsorship disclosure together.\n\nBest,\nPrenew marketing team\n\n[Demo draft — verify all facts and replace the sender details before use.]`}
function pipeline(){const entries=Object.entries(state.pipeline);shell(`<div class="head"><div><div class="eyebrow">Collaboration pipeline</div><h1>From first fit to confirmed.</h1><p class="muted">${entries.length} creators saved locally. Review candidates before preparing outreach.</p></div><div class="actions"><button id="export-shortlist">Export shortlist CSV</button><button data-nav="research" class="primary">Discover creators ＋</button></div></div><div class="banner">Manual tracking only. “Contacted”, “Replied” and “Confirmed” record a status you choose; they do not send messages or verify external activity.</div>${entries.length?`<div class="panel tablewrap"><table><thead><tr><th>Creator</th><th>Platform</th><th>Review</th><th>Draft approval</th><th>Status</th><th></th></tr></thead><tbody>${entries.map(([id,p])=>{const c=creators.find(c=>c.id===id);return `<tr><td><b>${esc(c.name)}</b><br><small>${c.sourceType==='live'?'YouTube API':c.sourceType==='imported'?'CSV import':'Fictional sample'}</small></td><td>${esc(c.platform)}</td><td>${esc(p.review||'Unreviewed')}</td><td>${p.approved?'✓ Approved':'Needs review'}</td><td><select aria-label="Status for ${esc(c.name)}" data-status="${id}">${statuses.map(s=>`<option ${p.status===s?'selected':''} ${s!=='Shortlisted'&&(!p.approved||p.review==='Rejected')?'disabled':''}>${s}</option>`).join('')}</select></td><td><button data-detail="${id}">Open →</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="panel empty"><h2>Your first collaboration starts here.</h2><p class="muted">Explore a creator and add them to your shortlist.</p><button data-nav="research">Find a creator →</button></div>'}`)}
function bind(){document.querySelector('#export-shortlist')?.addEventListener('click',()=>exportShortlist(state,creators));document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;selected=null;render()});document.querySelector('#campaign-form')?.addEventListener('submit',e=>{e.preventDefault();const next=Object.fromEntries(new FormData(e.target));next.budget=Number(next.budget);if(Object.keys(next).some(k=>next[k]!==state.campaign[k])){for(const p of Object.values(state.pipeline)){p.approved=false;p.draft='';p.concept=null;p.status='Shortlisted'}}state.campaign=next;state.saved=true;save();platform=next.platform;if(state.research){state.research.goal=next.goal;state.research.query='';}view='research';render();toast('Campaign saved. Recommendations updated.')});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{selected=b.dataset.detail;render();window.scrollTo(0,0)});document.querySelector('#back')?.addEventListener('click',()=>{selected=null;render()});document.querySelector('#search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)});document.querySelector('#platform')?.addEventListener('change',e=>{platform=e.target.value;render()});document.querySelector('#sort')?.addEventListener('change',e=>{sort=e.target.value;render()});document.querySelectorAll('[data-weight]').forEach(el=>el.onchange=()=>{state.weights[el.dataset.weight]=Number(el.value);save();render();document.querySelector('details').open=true});document.querySelectorAll('[data-compare]').forEach(el=>el.onchange=()=>{if(el.checked&&compare.length>=3){el.checked=false;toast('Compare up to three creators.');return}compare=el.checked?[...compare,el.dataset.compare]:compare.filter(x=>x!==el.dataset.compare);render()});document.querySelector('#compare-show')?.addEventListener('click',()=>{compareView=!compareView;render();if(compareView)document.querySelector('.tablewrap').scrollIntoView({behavior:'smooth',block:'center'})});document.querySelector('#shortlist')?.addEventListener('click',()=>{ensure(selected);save();render();toast('Creator saved to your pipeline.')});document.querySelectorAll('[data-idea]').forEach(b=>b.onclick=()=>{const p=ensure(selected);p.concept=Number(b.dataset.idea);p.draft='';p.approved=false;p.status='Shortlisted';save();render()});document.querySelector('#generate')?.addEventListener('click',()=>{const p=ensure(selected);if(p.draft&&!confirm('Replace your current draft with a newly generated draft?'))return;p.draft=draft(creators.find(c=>c.id===selected),p);p.approved=false;p.status='Shortlisted';save();render()});document.querySelector('#draft')?.addEventListener('input',e=>{const p=ensure(selected);p.draft=e.target.value;p.approved=false;p.status='Shortlisted';save();const b=document.querySelector('#approve');b.disabled=!p.draft.trim();b.textContent='Approve draft'});document.querySelector('#approve')?.addEventListener('click',()=>{const p=ensure(selected);if(!p.draft.trim())return;p.approved=true;p.status='Ready to Contact';save();render();toast('Draft approved. Ready to Contact — nothing sent.')});document.querySelectorAll('[data-status]').forEach(el=>el.onchange=()=>{const p=state.pipeline[el.dataset.status];if(el.value!=='Shortlisted'&&(!p.approved||p.review==='Rejected'))return;p.status=el.value;save();toast('Status saved. No message was sent.')})}
render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_campaign_pipeline',description:'Read the local campaign and manually tracked creator statuses. Makes no changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||Object.keys(input).length)throw new Error('Expected an empty object');return {campaign:state.campaign,pipeline:state.pipeline}}})}catch{}}
